using Pre2Port.Native;

namespace Pre2Port.Game.Frontend;

/// <summary>
/// Port-only (FULLSCREEN=WIDESCREEN, presentation only): side margins of the PRESENT screen, generated by RULES from the game's own 320x200
/// frame. No image data is stored: imagen/Extendido.png (a hand-widened PRESENT) was used only as a reference to choose the rules below
/// (which source strip feeds each band of rows, how wide, and how much it is shifted), never as pixels.
/// Rule per band of rows: the margin pixel at distance d from the frame edge copies the frame pixel at distance s from that edge, where
/// s walks the strip [0, W) back and forth (mirror, so the seam with the real art is continuous). Each tile of W pixels (k = d / W) also
/// moves its source row by dy(k), clamped to the band, so the repetition does not read as a kaleidoscope. Because the pixels are the
/// frame's own indices the game palette (and its fades) apply unchanged.
/// </summary>
public static class WideArt
{
    /// <summary>One band of rows: [Y0, Y1), strip width W, row-shift amplitude Step (0 = none).</summary>
    readonly record struct Band(int Y0, int Y1, int W, int Step);

    // Left: cliff face (0..127; W 24 stays left of the logo), mixed rock/ferns (128..161), jungle (162..199).
    static readonly Band[] Left = { new(0, 128, 24, 9), new(128, 162, 16, 0), new(162, 200, 24, 5) };
    // Right: sky with its dither (0..99; the logo "K" ends before the last 8 columns), green plain (100..167), jungle (168..199).
    static readonly Band[] Right = { new(0, 100, 8, 0), new(100, 168, 12, 0), new(168, 200, 24, 5) };

    /// <summary>Copies the 320 frame <paramref name="src"/> centred into <paramref name="dst"/> (palette included) and fills both margins by the band rules.</summary>
    public static void Present(Framebuffer src, Framebuffer dst)
    {
        int w = dst.Width, sw = src.Width, m = (w - sw) / 2, mr = w - m - sw;
        Array.Copy(src.Palette, dst.Palette, dst.Palette.Length);
        for (int y = 0; y < dst.Height; y++) Array.Copy(src.Pixels, y * sw, dst.Pixels, y * w + m, sw);
        Fill(src, dst, Left, m, left: true);
        Fill(src, dst, Right, mr, left: false);
    }

    static void Fill(Framebuffer src, Framebuffer dst, Band[] bands, int margin, bool left)
    {
        int w = dst.Width, sw = src.Width, m = (w - sw) / 2;
        foreach (var b in bands)
            for (int y = b.Y0; y < b.Y1 && y < dst.Height; y++)
                for (int d = 0; d < margin; d++)
                {
                    int k = d / b.W, t = d % (2 * b.W), s = t < b.W ? t : 2 * b.W - 1 - t;
                    int dy = b.Step == 0 ? 0 : k * b.Step % (2 * b.Step + 1) - b.Step;
                    int sy = Math.Clamp(y + dy, b.Y0, b.Y1 - 1);
                    byte v = src.Pixels[sy * sw + (left ? s : sw - 1 - s)];
                    dst.Pixels[y * w + (left ? m - 1 - d : m + sw + d)] = v;
                }
    }
}
